\"\"\"Send private text prompts to the OpenAI Responses API.

Stdlib only. Prompt text is sent in the request body and is not written to
disk by this module. "'``store`` is always false so the API is asked not to
persist the response for later retrieval.

Official reference (unreachable from this environment when this module was
written): https://developers.openai.com/api/reference/resources/responses/methods/create
"""

from __future__ import annotations

import json
import os
import sys
import urllib.error
import urllib.request
from typing import Any, Mapping

DEFAULT_BASE_URL = "https://api.openai.com/v1"


class OpenAIError(RuntimeError):
    """Raised when the Responses API cannot return text."""

    def __init__(
        self,
        message: str,
        *,
        status: int | None = None,
        body: str | None = None,
    ) -> None:
        super().__init__(message)
        self.status = status
        self.body = body


def _api_key(explicit: str | None) -> str:
    key = explicit if explicit is not None else os.environ.get("OPENAI_API_KEY")
    if key is None or not key.strip():
        raise OpenAIError("Missing API key. Set OPENAI_API_KEY or pass api_key.")
    return key.strip()


def _model(explicit: str | None) -> str:
    chosen = explicit if explicit is not None else os.environ.get("OPENAI_MODEL")
    if chosen is None or not chosen.strip():
        raise ValueError("model is required. Pass model= or set OPENAI_MODEL.")
    return chosen.strip()


def _extract_text(payload: Mapping[str, Any]) -> str:
    direct = payload.get("output_text")
    if isinstance(direct, str) and direct:
        return direct

    parts: list[str] = []
    output = payload.get("output")
    if isinstance(output, list):
        for item in output:
            if not isinstance(item, dict):
                continue
            if item.get("type") == "output_text" and isinstance(item.get("text"), str):
                parts.append(item["text"])
                continue
            content = item.get("content")
            if isinstance(content, str):
                parts.append(content)
                continue
            if not isinstance(content, list):
                continue
            for block in content:
                if not isinstance(block, dict):
                    continue
                if block.get("type") in {"output_text", "text"} and isinstance(
                    block.get("text"), str
                ):
                    parts.append(block["text"])
    if parts:
        return "".join(parts)
    raise OpenAIError("Response did not include text output.")


def send_text(
    prompt: str,
    *,
    model: str | None = None,
    api_key: str | None = None,
    instructions: str | None = None,
    timeout: float = 120.0,
    base_url: str = DEFAULT_BASE_URL,
    extra: Mapping[str, Any] | None = None,
) -> str:
    """Send one private text prompt and return the assistant text.

    The API key is read from ``api_key`` or ``OPENAI_API_KEY`` and is only
    placed in the Authorization header. It is not logged or written to a file.
    """
    if not isinstance(prompt, str) or not prompt.strip():
        raise ValueError("prompt must be a non-empty string")

    body: dict[str, Any] = {
        "model": _model(model),
        "input": prompt,
        "store": False,
    }
    if instructions is not None:
        if not isinstance(instructions, str):
            raise ValueError("instructions must be a string")
        body["instructions"] = instructions
    if extra:
        if "store" in extra:
            raise ValueError("extra cannot override store")
        body.update(extra)

    request = urllib.request.Request(
        base_url.rstrip("/") + "/responses",
        data=json.dumps(body).encode("utf-8"),
        method="POST",
        headers={
            "Authorization": f"Bearer {_api_key(api_key)}",
            "Content-Type": "application/json",
            "Accept": "application/json",
        },
    )
    try:
        with urllib.request.urlopen(request, timeout=timeout) as response:
            raw = response.read().decode("utf-8")
    except urllib.error.HTTPError as exc:
        detail = exc.read().decode("utf-8", errors="replace")
        raise OpenAIError(
            f"Responses API request failed with HTTP {exc.code}",
            status=exc.code,
            body=detail,
        ) from exc
    except urllib.error.URLError as exc:
        raise OpenAIError(f"Could not reach the Responses API: {exc.reason}") from exc

    try:
        payload = json.loads(raw)
    except json.JSONDecodeError as exc:
        raise OpenAIError("Responses API returned invalid JSON") from exc
    if not isinstance(payload, dict):
        raise OpenAIError("Unexpected Responses API payload")

    status = payload.get("status")
    if status not in (None, "completed"):
        error = payload.get("error")
        detail = error if isinstance(error, str) else None
        raise OpenAIError(f"Responses API status is {status}", body=detail)
    return _extract_text(payload)


def main(argv: list[str] | None = None) -> int:
    """Read a prompt from stdin and print the response text.

    Usage: OPENAI_MODEL=... python openai_client.py [model]
    Optional instructions can be passed with --instructions TEXT.
    """
    args = list(sys.argv[1:] if argv is None else argv)
    instructions = None
    if "--instructions" in args:
        index = args.index("--instructions")
        try:
            instructions = args[index + 1]
        except IndexError:
            print("missing value for --instructions", file=sys.stderr)
            return 2
        del args[index : index + 2]
    model = args[0] if args else None
    prompt = sys.stdin.read()
    try:
        sys.stdout.write(send_text(prompt, model=model, instructions=instructions))
        if not sys.stdout.isatty():
            sys.stdout.write("'"\\n\")
    except (OpenAIError, ValueError) as exc:
        print(str(exc), file=sys.stderr)
        return 1
    return 0


if __name__ == \"__main__\":
    raise SystemExit(main())
